"""
Paper 1 -- fixes a critical bug a fresh review caught in the causal-patching
test (Sec 3.4): the "Attention-patch control" in every prior version of this
experiment (code/01_ffn_causal_patch.py, code/10, code/14, and the judge-
label kernel paper1-causal-patch-judge-label) injects the SAME FFN-derived
direction used for the FFN arm, just at a different hook site (the
attention sublayer's own output instead of the MLP's). There has never
been a genuinely Attention-derived direction anywhere in this paper's
codebase. The "component specificity" claim -- that patching FFN changes
behavior but patching Attention does not -- was therefore never actually
tested: both arms differ only in WHERE the same vector is injected into
the residual stream, not in WHICH component's own discriminative direction
is used.

This script fixes that: it computes a genuine Attention-derived
difference-of-means direction (mean-pooled last-token ATTENTION sublayer
output, correct minus hallucinated, on the judge-labeled train split --
identical methodology to the existing FFN direction, just hooking .attn
instead of .mlp), plus its own random-orthogonal control, and reruns the
causal-patching loop with FOUR conditions instead of three:
  - ffn_found:  FFN-direction  -> FFN site   (existing)
  - ffn_rand:   FFN-random     -> FFN site   (existing)
  - attn_found: ATTN-direction -> ATTN site  (NEW -- the real test)
  - attn_rand:  ATTN-random    -> ATTN site  (NEW)

This gives a genuine FFN-vs-Attention component-specificity test:
FFN-found vs. Attn-found, each measured against its OWN random-direction
control, at the same layers/alphas/judge-labeled test set as the existing
flagship result (n=467 judge-hallucinated GPT-2 test prompts).
"""
import base64
import gzip
import json
import time
from pathlib import Path

import numpy as np
import torch
from datasets import load_dataset
from scipy.stats import binomtest
from transformers import AutoModelForCausalLM, AutoTokenizer, GPT2LMHeadModel, GPT2Tokenizer

OUT_DIR = Path("/kaggle/working")

LABELED_DATA_B64 = ""


def load_labeled_data():
    compressed = base64.b64decode(LABELED_DATA_B64)
    return json.loads(gzip.decompress(compressed))


JUDGE_MODEL = "Qwen/Qwen2.5-3B-Instruct"
TARGET_LAYER = 8
SECOND_LAYER = 9
ALPHAS = [20.0, 40.0]
MAX_NEW_TOKENS = 40
LABEL_THRESHOLD = 0.12
TRAIN_N_PER_CLASS = 40
RANDOM_STATE = 42

JUDGE_PROMPT = """You are a factuality judge. You will be given a question, the correct reference answer, and a model's answer.
Decide if the model's answer is CORRECT or HALLUCINATED.
A response is CORRECT if its core factual claim matches or is consistent with the reference answer, even if phrased differently.
A response is HALLUCINATED if it asserts something factually wrong, contradicts the reference, or fails to answer.
Ignore phrasing differences and focus only on factual accuracy.

Question: {question}
Reference answer: {reference}
Model's answer: {response}

Reply with exactly one word: CORRECT or HALLUCINATED."""


def query_judge(model, tokenizer, device, question, reference, response):
    prompt = JUDGE_PROMPT.format(question=question, reference=reference, response=response)
    messages = [{"role": "user", "content": prompt}]
    text = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
    inputs = tokenizer(text, return_tensors="pt", truncation=True, max_length=512).to(device)
    with torch.no_grad():
        out_ids = model.generate(**inputs, max_new_tokens=8, do_sample=False,
                                  pad_token_id=tokenizer.eos_token_id)
    verdict = tokenizer.decode(out_ids[0][inputs["input_ids"].shape[1]:], skip_special_tokens=True).strip().upper()
    # CORRECTION (post-review): "CORRECT" in verdict matched the
    # substring "CORRECT" inside "INCORRECT" too, silently mis-scoring
    # any judge output containing the word "incorrect" as label=1.
    # Check HALLUCINAT and INCORRECT first (both -> hallucinated/wrong),
    # only then treat a bare "CORRECT" as label=1.
    if "HALLUCINAT" in verdict:
        return 0
    if "INCORRECT" in verdict:
        return 0
    if "CORRECT" in verdict:
        return 1
    return -1


def question_from_prompt(prompt: str) -> str:
    return prompt.split("Q:", 1)[1].split("\nA:", 1)[0].strip()


def _word_overlap(a, b):
    wa, wb = set(a.lower().split()), set(b.lower().split())
    if not wa or not wb:
        return 0.0
    return len(wa & wb) / len(wa | wb)


def jaccard_label(completion, correct_answers, incorrect_answers):
    best_correct = max((_word_overlap(completion, a) for a in correct_answers), default=0.0)
    best_incorrect = max((_word_overlap(completion, a) for a in incorrect_answers), default=0.0)
    if best_correct > LABEL_THRESHOLD or best_incorrect > LABEL_THRESHOLD:
        return 1 if best_correct >= best_incorrect else 0
    return -1


def extract_last_token(prompt, model, tokenizer, device, layer_idx, sublayer):
    captured = {}

    def hook(module, inp, out):
        t = out[0] if isinstance(out, tuple) else out
        captured["v"] = t[0, -1, :].detach().cpu().float().numpy().copy()

    module = (model.transformer.h[layer_idx].mlp if sublayer == "mlp"
              else model.transformer.h[layer_idx].attn)
    h = module.register_forward_hook(hook)
    try:
        inputs = tokenizer(prompt, return_tensors="pt", truncation=True, max_length=128)
        input_ids = inputs["input_ids"].to(device)
        with torch.no_grad():
            model(input_ids=input_ids)
    finally:
        h.remove()
    return captured["v"]


def compute_direction(train_prompts, train_labels, model, tokenizer, device, layer_idx, sublayer):
    correct_vecs, hall_vecs = [], []
    for p, y in zip(train_prompts, train_labels):
        vec = extract_last_token(p, model, tokenizer, device, layer_idx, sublayer)
        (correct_vecs if y == 1 else hall_vecs).append(vec)
    direction = np.mean(correct_vecs, axis=0) - np.mean(hall_vecs, axis=0)
    norm = np.linalg.norm(direction)
    if norm < 1e-8:
        raise ValueError(f"{sublayer} direction near zero.")
    return direction / norm, len(correct_vecs), len(hall_vecs)


def random_orthogonal_direction(direction, seed=42):
    rng = np.random.default_rng(seed)
    v = rng.standard_normal(direction.shape)
    v -= np.dot(v, direction) * direction
    v /= np.linalg.norm(v)
    return v


def patched_generate(prompt, model, tokenizer, device, layer_idx, direction, alpha, sublayer):
    direction_t = torch.tensor(direction, dtype=torch.float32, device=device)

    def hook(module, inp, out):
        if sublayer == "mlp":
            return out + alpha * direction_t
        modified = out[0] + alpha * direction_t
        return (modified,) + out[1:]

    module = (model.transformer.h[layer_idx].mlp if sublayer == "mlp"
              else model.transformer.h[layer_idx].attn)
    handle = module.register_forward_hook(hook)
    try:
        inputs = tokenizer(prompt, return_tensors="pt", truncation=True, max_length=128)
        input_ids = inputs["input_ids"].to(device)
        with torch.no_grad():
            output_ids = model.generate(input_ids, max_new_tokens=MAX_NEW_TOKENS, do_sample=False,
                                         pad_token_id=tokenizer.eos_token_id)
        return tokenizer.decode(output_ids[0][input_ids.shape[1]:], skip_special_tokens=True).strip()
    finally:
        handle.remove()


def unpatched_generate(prompt, model, tokenizer, device):
    inputs = tokenizer(prompt, return_tensors="pt", truncation=True, max_length=128)
    input_ids = inputs["input_ids"].to(device)
    with torch.no_grad():
        output_ids = model.generate(input_ids, max_new_tokens=MAX_NEW_TOKENS, do_sample=False,
                                     pad_token_id=tokenizer.eos_token_id)
    return tokenizer.decode(output_ids[0][input_ids.shape[1]:], skip_special_tokens=True).strip()


def mcnemar_pair(rows, key, field_a, field_b):
    flip_a = [r[f"{key}_{field_a}"] == 1 for r in rows]
    flip_b = [r[f"{key}_{field_b}"] == 1 for r in rows]
    b = sum(1 for a, bb in zip(flip_a, flip_b) if a and not bb)
    c = sum(1 for a, bb in zip(flip_a, flip_b) if not a and bb)
    p = binomtest(b, b + c, 0.5).pvalue if (b + c) > 0 else 1.0
    return b, c, float(p), float(np.mean(flip_a)), float(np.mean(flip_b))


def summarize(rows, key, label_suffix):
    ffn_found_vs_rand = mcnemar_pair(rows, key, f"ffn_found_{label_suffix}", f"ffn_rand_{label_suffix}")
    attn_found_vs_rand = mcnemar_pair(rows, key, f"attn_found_{label_suffix}", f"attn_rand_{label_suffix}")
    ffn_vs_attn_found = mcnemar_pair(rows, key, f"ffn_found_{label_suffix}", f"attn_found_{label_suffix}")
    return {
        "n": len(rows),
        "ffn_found_flip_rate": round(ffn_found_vs_rand[3], 4),
        "ffn_rand_flip_rate": round(ffn_found_vs_rand[4], 4),
        "attn_found_flip_rate": round(attn_found_vs_rand[3], 4),
        "attn_rand_flip_rate": round(attn_found_vs_rand[4], 4),
        "mcnemar_ffn_found_vs_rand": {"b": ffn_found_vs_rand[0], "c": ffn_found_vs_rand[1], "p": round(ffn_found_vs_rand[2], 4)},
        "mcnemar_attn_found_vs_rand": {"b": attn_found_vs_rand[0], "c": attn_found_vs_rand[1], "p": round(attn_found_vs_rand[2], 4)},
        "mcnemar_ffn_found_vs_attn_found": {"b": ffn_vs_attn_found[0], "c": ffn_vs_attn_found[1], "p": round(ffn_vs_attn_found[2], 4)},
    }


def main():
    t0 = time.time()
    device = "cuda" if torch.cuda.is_available() else "cpu"
    print(f"Device: {device}", flush=True)

    labeled = load_labeled_data()
    prompts, jaccard_labels_orig, completions = labeled["prompts"], labeled["labels"], labeled["completions"]
    print(f"Loaded {len(prompts)} GPT-2 labeled examples", flush=True)

    ds = load_dataset("truthful_qa", "generation", split="validation")
    qmap_judge = {item["question"].strip(): item["best_answer"] for item in ds}
    qmap_jaccard = {item["question"].strip(): (item["correct_answers"], item["incorrect_answers"]) for item in ds}

    print(f"Loading judge model {JUDGE_MODEL}...", flush=True)
    judge_tok = AutoTokenizer.from_pretrained(JUDGE_MODEL)
    judge_dtype = torch.float16 if device == "cuda" else torch.float32
    judge_model = AutoModelForCausalLM.from_pretrained(JUDGE_MODEL, torch_dtype=judge_dtype).to(device)
    judge_model.eval()

    print(f"\nJudging all {len(prompts)} original GPT-2 completions...", flush=True)
    judge_labels = []
    for i, (prompt, completion) in enumerate(zip(prompts, completions)):
        q = question_from_prompt(prompt)
        ref = qmap_judge.get(q)
        if ref is None:
            judge_labels.append(-1)
            continue
        judge_labels.append(query_judge(judge_model, judge_tok, device, q, ref, completion))
        if (i + 1) % 100 == 0:
            print(f"  judged {i+1}/{len(prompts)}", flush=True)

    judge_labels = np.array(judge_labels)
    valid_mask = judge_labels != -1
    n_correct = int((judge_labels[valid_mask] == 1).sum())
    n_hall = int((judge_labels[valid_mask] == 0).sum())
    print(f"\nJudge labeling done: n_valid={valid_mask.sum()} correct={n_correct} hallucinated={n_hall}", flush=True)
    agreement = float((judge_labels[valid_mask] == np.array(jaccard_labels_orig)[valid_mask]).mean())

    valid_idx = np.where(valid_mask)[0]
    correct_idx = [i for i in valid_idx if judge_labels[i] == 1]
    hall_idx = [i for i in valid_idx if judge_labels[i] == 0]
    rng = np.random.default_rng(RANDOM_STATE)
    rng.shuffle(correct_idx)
    rng.shuffle(hall_idx)

    n_train_correct = min(TRAIN_N_PER_CLASS, int(0.7 * len(correct_idx)) if len(correct_idx) < TRAIN_N_PER_CLASS * 2 else TRAIN_N_PER_CLASS)
    n_train_hall = min(TRAIN_N_PER_CLASS, int(0.7 * len(hall_idx)) if len(hall_idx) < TRAIN_N_PER_CLASS * 2 else TRAIN_N_PER_CLASS)
    n_train_correct = max(n_train_correct, min(5, len(correct_idx)))
    n_train_hall = max(n_train_hall, min(5, len(hall_idx)))

    train_correct_idx = correct_idx[:n_train_correct]
    train_hall_idx = hall_idx[:n_train_hall]
    train_idx = train_correct_idx + train_hall_idx
    hallucinated_test_idx = hall_idx[n_train_hall:]

    print(f"\nTrain: {len(train_idx)} ({len(train_correct_idx)} correct, {len(train_hall_idx)} hallucinated)")
    print(f"Test (judge-hallucinated, all remaining): {len(hallucinated_test_idx)}", flush=True)

    train_prompts = [prompts[i] for i in train_idx]
    train_labels_judge = [int(judge_labels[i]) for i in train_idx]

    print(f"\nLoading GPT-2...", flush=True)
    gpt2_tok = GPT2Tokenizer.from_pretrained("gpt2")
    gpt2 = GPT2LMHeadModel.from_pretrained("gpt2").to(device)
    gpt2.eval()

    directions = {}
    for layer_idx in (TARGET_LAYER, SECOND_LAYER):
        print(f"Computing FFN direction at L{layer_idx}...", flush=True)
        ffn_dir, ncf, nhf = compute_direction(train_prompts, train_labels_judge, gpt2, gpt2_tok, device, layer_idx, "mlp")
        ffn_rand = random_orthogonal_direction(ffn_dir, seed=RANDOM_STATE)
        print(f"Computing REAL Attention direction at L{layer_idx}...", flush=True)
        attn_dir, nca, nha = compute_direction(train_prompts, train_labels_judge, gpt2, gpt2_tok, device, layer_idx, "attn")
        attn_rand = random_orthogonal_direction(attn_dir, seed=RANDOM_STATE + 1)
        # cosine similarity between the two directions, diagnostic
        cos_sim = float(np.dot(ffn_dir, attn_dir))
        print(f"  L{layer_idx}: FFN dir vs Attn dir cosine similarity = {cos_sim:.4f}", flush=True)
        directions[layer_idx] = {"ffn": ffn_dir, "ffn_rand": ffn_rand, "attn": attn_dir, "attn_rand": attn_rand, "cos_sim": cos_sim}

    print(f"\nRunning causal-patching loop (4 conditions) on {len(hallucinated_test_idx)} test prompts...", flush=True)
    results = []
    n = len(hallucinated_test_idx)
    for progress_i, i in enumerate(hallucinated_test_idx):
        prompt = prompts[i]
        question = question_from_prompt(prompt)
        if question not in qmap_judge or question not in qmap_jaccard:
            continue
        ref_judge = qmap_judge[question]
        correct_answers, incorrect_answers = qmap_jaccard[question]

        row = {"idx": int(i), "prompt": prompt}
        baseline_completion = unpatched_generate(prompt, gpt2, gpt2_tok, device)
        row["baseline_judge_label"] = query_judge(judge_model, judge_tok, device, question, ref_judge, baseline_completion)
        row["baseline_jaccard_label"] = jaccard_label(baseline_completion, correct_answers, incorrect_answers)

        for layer_idx in (TARGET_LAYER, SECOND_LAYER):
            d = directions[layer_idx]
            for alpha in ALPHAS:
                ffn_found_c = patched_generate(prompt, gpt2, gpt2_tok, device, layer_idx, d["ffn"], alpha, "mlp")
                ffn_rand_c = patched_generate(prompt, gpt2, gpt2_tok, device, layer_idx, d["ffn_rand"], alpha, "mlp")
                attn_found_c = patched_generate(prompt, gpt2, gpt2_tok, device, layer_idx, d["attn"], alpha, "attn")
                attn_rand_c = patched_generate(prompt, gpt2, gpt2_tok, device, layer_idx, d["attn_rand"], alpha, "attn")

                key = f"L{layer_idx}_a{int(alpha)}"
                for cname, ctext in (("ffn_found", ffn_found_c), ("ffn_rand", ffn_rand_c),
                                      ("attn_found", attn_found_c), ("attn_rand", attn_rand_c)):
                    row[f"{key}_{cname}_judge_label"] = query_judge(judge_model, judge_tok, device, question, ref_judge, ctext)
                    row[f"{key}_{cname}_jaccard_label"] = jaccard_label(ctext, correct_answers, incorrect_answers)

        results.append(row)
        if (progress_i + 1) % 20 == 0:
            elapsed = time.time() - t0
            eta = (elapsed / (progress_i + 1)) * (n - progress_i - 1) / 60
            print(f"  [{progress_i + 1}/{n}] elapsed={elapsed:.0f}s ETA={eta:.0f}min", flush=True)

    summary_judge, summary_jaccard = {}, {}
    for layer_idx in (TARGET_LAYER, SECOND_LAYER):
        for alpha in ALPHAS:
            key = f"L{layer_idx}_a{int(alpha)}"
            summary_judge[key] = summarize(results, key, "judge_label")
            summary_jaccard[key] = summarize(results, key, "jaccard_label")

    print("\n=== UNDER JUDGE LABEL ===")
    for key, s in summary_judge.items():
        print(f"  {key}: FFN-found={s['ffn_found_flip_rate']:.3f} FFN-rand={s['ffn_rand_flip_rate']:.3f} "
              f"Attn-found={s['attn_found_flip_rate']:.3f} Attn-rand={s['attn_rand_flip_rate']:.3f}")
        print(f"    McNemar FFN found-vs-rand: p={s['mcnemar_ffn_found_vs_rand']['p']}")
        print(f"    McNemar Attn found-vs-rand: p={s['mcnemar_attn_found_vs_rand']['p']}")
        print(f"    McNemar FFN-found vs Attn-found (REAL component-specificity test): p={s['mcnemar_ffn_found_vs_attn_found']['p']}")

    print("\n=== UNDER JACCARD LABEL ===")
    for key, s in summary_jaccard.items():
        print(f"  {key}: FFN-found={s['ffn_found_flip_rate']:.3f} FFN-rand={s['ffn_rand_flip_rate']:.3f} "
              f"Attn-found={s['attn_found_flip_rate']:.3f} Attn-rand={s['attn_rand_flip_rate']:.3f}")
        print(f"    McNemar FFN found-vs-rand: p={s['mcnemar_ffn_found_vs_rand']['p']}")
        print(f"    McNemar Attn found-vs-rand: p={s['mcnemar_attn_found_vs_rand']['p']}")
        print(f"    McNemar FFN-found vs Attn-found (REAL component-specificity test): p={s['mcnemar_ffn_found_vs_attn_found']['p']}")

    out = {
        "config": {"target_layer": TARGET_LAYER, "second_layer": SECOND_LAYER, "alphas": ALPHAS,
                   "max_new_tokens": MAX_NEW_TOKENS, "train_n_correct": len(train_correct_idx),
                   "train_n_hall": len(train_hall_idx)},
        "direction_cosine_similarity": {str(l): directions[l]["cos_sim"] for l in directions},
        "judge_relabel_stats": {"n_valid": int(valid_mask.sum()), "n_correct": n_correct, "n_hall": n_hall,
                                 "agreement_with_jaccard": agreement},
        "n_hallucinated_test": len(results),
        "summary_under_judge_label": summary_judge,
        "summary_under_jaccard_label": summary_jaccard,
        "per_sample": results,
    }
    out_path = OUT_DIR / "causal_patch_real_attn_direction_results.json"
    with open(out_path, "w") as f:
        json.dump(out, f, indent=2)
    print(f"\nSaved: {out_path}")
    print(f"Total runtime: {(time.time()-t0)/60:.1f} min")


if __name__ == "__main__":
    main()
